    30→const SIDEBAR_COOKIE_NAME = "sidebar_state";
    31→const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
    32→const SIDEBAR_WIDTH = "16rem";
    33→const SIDEBAR_WIDTH_MOBILE = "18rem";
    34→const SIDEBAR_WIDTH_ICON = "3rem";
    35→const SIDEBAR_KEYBOARD_SHORTCUT = "b";
    36→
    37→type SidebarContextProps = {
    38→  state: "expanded" | "collapsed";
    39→  open: boolean;
    40→  setOpen: (open: boolean) => void;
    41→  openMobile: boolean;
    42→  setOpenMobile: (open: boolean) => void;
    43→  isMobile: boolean;
    44→  toggleSidebar: () => void;
    45→};
    46→
    47→const SidebarContext = React.createContext<SidebarContextProps | null>(null);
    48→
    49→function useSidebar() {
    50→  const context = React.useContext(SidebarContext);
    51→  if (!context) {
    52→    throw new Error("useSidebar must be used within a SidebarProvider.");
    53→  }
    54→
    55→  return context;
    56→}
    57→
    58→function SidebarProvider({
    59→  defaultOpen = true,
    60→  open: openProp,
    61→  onOpenChange: setOpenProp,
    62→  className,
    63→  style,
    64→  children,
    65→  ...props
    66→}: React.ComponentProps<"div"> & {
    67→  defaultOpen?: boolean;
    68→  open?: boolean;
    69→  onOpenChange?: (open: boolean) => void;
    70→}) {
    71→  const isMobile = useIsMobile();
    72→  const [openMobile, setOpenMobile] = React.useState(false);
    73→
    74→  // This is the internal state of the sidebar.
    75→  // We use openProp and setOpenProp for control from outside the component.
    76→  const [_open, _setOpen] = React.useState(defaultOpen);
    77→  const open = openProp ?? _open;
    78→
    79→  const setOpen = React.useCallback(
    80→    (value: boolean | ((value: boolean) => boolean)) => {
    81→      const openState = typeof value === "function" ? value(open) : value;
    82→      if (setOpenProp) {
    83→        setOpenProp(openState);
    84→      } else {
    85→        _setOpen(openState);
    86→      }
    87→
    88→      // This sets the cookie to keep the sidebar state.
    89→      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    90→    },
    91→    [setOpenProp, open],
    92→  );
    93→
    94→  // Helper to toggle the sidebar.
    95→  const toggleSidebar = React.useCallback(() => {
    96→    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
    97→  }, [isMobile, setOpen, setOpenMobile]);
    98→
    99→  // Adds a keyboard shortcut to toggle the sidebar.
   100→  React.useEffect(() => {
   101→    const handleKeyDown = (event: KeyboardEvent) => {
   102→      if (
   103→        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
   104→        (event.metaKey || event.ctrlKey)
   105→      ) {
   106→        event.preventDefault();
   107→        toggleSidebar();
   108→      }
   109→    };
   110→
   111→    window.addEventListener("keydown", handleKeyDown);
   112→    return () => window.removeEventListener("keydown", handleKeyDown);
   113→  }, [toggleSidebar]);
   114→
   115→  // Initialize sidebar state from cookie when component mounts
   116→  React.useEffect(() => {
   117→    // Only run on client-side
   118→    if (typeof document !== "undefined") {
   119→      const cookies = document.cookie.split(";");
   120→      const sidebarCookie = cookies.find((cookie) =>
   121→        cookie.trim().startsWith(`${SIDEBAR_COOKIE_NAME}=`),
   122→      );
   123→
   124→      if (sidebarCookie) {
   125→        const cookieValue = sidebarCookie.split("=")[1];
   126→        const isOpen = cookieValue === "true";
   127→
   128→        // Only update if we're not controlled externally
   129→        if (setOpenProp === undefined) {
   130→          _setOpen(isOpen);
   131→        }
   132→      }
   133→    }
   134→  }, [setOpenProp]);
   135→
   136→  // We add a state so that we can do data-state="expanded" or "collapsed".
   137→  // This makes it easier to style the sidebar with Tailwind classes.
   138→  const state = open ? "expanded" : "collapsed";
   139→
   140→  const contextValue = React.useMemo<SidebarContextProps>(
   141→    () => ({
   142→      state,
   143→      open,
   144→      setOpen,
   145→      isMobile,
   146→      openMobile,
   147→      setOpenMobile,
   148→      toggleSidebar,
   149→    }),
   150→    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
   151→  );
   152→
   153→  return (
   154→    <SidebarContext.Provider value={contextValue}>
   155→      <TooltipProvider delayDuration={0}>
   156→        <div
   157→          data-slot="sidebar-wrapper"
   158→          style={
   159→            {
   160→              "--sidebar-width": SIDEBAR_WIDTH,
   161→              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
   162→              ...style,
   163→            } as React.CSSProperties
   164→          }
   165→          className={cn(
   166→            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
   167→            className,
   168→          )}
   169→          {...props}
   170→        >
   171→          {children}
   172→        </div>
   173→      </TooltipProvider>
   174→    </SidebarContext.Provider>
   175→  );
   176→}
